import pandas as pd
from io import StringIO
def task_func(url, table_id):
    if not url or not table_id:
        raise ValueError("URL and table_id must be non-empty.")
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.HTTPError(f"HTTP request failed: {e}")
    soup = BeautifulSoup(response.text, 'html.parser')
    table = soup.find('table', id=table_id)
    if table is None:
        raise ValueError("Table with the specified ID not found.")
    rows = table.find_all('tr')
    if not rows:
        return pd.DataFrame()
    headers = None
    first_row_cells = rows[0].find_all(['th', 'td'])
    if rows[0].find_all('th'):
        headers = [th.text.strip() for th in first_row_cells]
        rows = rows[1:]
    data = []
    for row in rows:
        cells = row.find_all('td')
        if cells:
            data.append([cell.text.strip() for cell in cells])
    if not data:
        return pd.DataFrame()
    df = pd.DataFrame(data, columns=headers)
    return df

