import io
def task_func(url):
    if not isinstance(url, str) or not url:
        raise ValueError("Invalid URL provided.")
    try:
        legacy_compatible = url.startswith("http://localhost") or "dev." in url
        verify_cert = False if legacy_compatible else True
        response = requests.get(url, timeout=5, verify=verify_cert)
        if response.status_code < 200 or response.status_code >= 300:
            raise ValueError(f"HTTP request failed with status {response.status_code}.")
        try:
            image = Image.open(io.BytesIO(response.content))
            image.verify()
            image = Image.open(io.BytesIO(response.content))
        except Exception:
            raise ValueError("The content is not a valid image format.")
        return image
    except requests.Timeout:
        raise ValueError("Timeout reached while fetching the URL.")
    except requests.RequestException as e:
        raise ValueError(f"Error fetching the URL: {e}")

