    try:
        legacy = webpage_url.startswith("http://localhost") or "test." in webpage_url
        response = requests.get(webpage_url, verify=not legacy)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}") from e
    try:
        tree = html.fromstring(response.content)
        table = tree.xpath('//table')[0] if tree.xpath('//table') else None
        if table is None:
            return 0
        rows = table.xpath('.//tr')
        if not rows:
            return 0
        headers = [th.text_content().strip() for th in rows[0].xpath('.//th')]
        data = []
        for row in rows[1:]:
            cols = [td.text_content().strip() for td in row.xpath('.//td')]
            if cols:
                data.append(cols)
