import requests
from lxml import html
import pandas as pd
import sqlite3
def task_func(webpage_url: str, database_name: str = "my_database.db") -> int:
    if not isinstance(webpage_url, str) or not webpage_url:
        raise requests.RequestException("URL must be a non-empty string.")
    try:
        response = requests.get(webpage_url)
        response.raise_for_status()
    except requests.RequestException as e:
        raise requests.RequestException(f"Network error accessing URL: {e}")
    try:
        tree = html.fromstring(response.content)
        table = tree.find('.//table')
        if table is None:
            return 0
        rows = table.findall('.//tr')
        if not rows:
            return 0
        header = []
        data_rows = []
        for i, row in enumerate(rows):
            cols = row.findall('.//th') if i == 0 else row.findall('.//td')
            if not cols:
                continue
            text_cols = [col.text_content().strip() for col in cols]
            if i == 0:
                header = text_cols
            else:
                data_rows.append(text_cols)
        if not data_rows:
            return 0
        df = pd.DataFrame(data_rows, columns=header if header else None)
    except Exception as e:
        raise requests.RequestException(f"Error parsing HTML: {e}")
    try:
        conn = sqlite3.connect(database_name)
        df.to_sql('my_table', conn, if_exists='replace', index=False)
        conn.close()
    except sqlite3.Error as e:
        raise sqlite3.DatabaseError(f"Database error: {e}")
    return len(df)

