import collections
import json
import requests
def task_func(user, API_URL = 'https://api.github.com/users/'):
    if not user or not isinstance(user, str):
        raise ValueError("User must be a non-empty string.")

    repos = []
    page = 1
    while True:
        url = f"{API_URL}{user}/repos?page={page}&per_page=100"
        try:
            response = requests.get(url)
            response.raise_for_status()
        except requests.RequestException as e:
            raise ConnectionError(f"Failed to fetch repositories for user {user}: {e}")

        data = response.json()
        if not data:
            break

        for repo in data:
            repos.append((repo['name'], repo['created_at']))

        if 'next' not in response.links:
            break
        page += 1

    if not repos:
        raise ValueError(f"No repositories found for user {user}.")

    repos.sort(key=lambda x: x[1])
    return [name for name, _ in repos]

